def summarize_usage(events):
    max_counts = {}
    for event in events:
        rid = event['request_id']
        inc = event.get('input', 0)
        outc = event.get('output', 0)
        if inc < 0 or outc < 0:
            raise ValueError("Token counts must be nonnegative")
        if rid not in max_counts:
            max_counts[rid] = {'input': 0, 'output': 0}
        max_counts[rid]['input'] = max(max_counts[rid]['input'], inc)
        max_counts[rid]['output'] = max(max_counts[rid]['output'], outc)
    tin = 0
    tout = 0
    for c in max_counts:
        tin += max_counts[c]['input']
        tout += max_counts[c]['output']
    return {'input': tin, 'output': tout}

